/**
 * Test: Datenbank-Client (Supabase)
 */

jest.mock('../../lib/supabase', () => ({
  supabase: {
    from: jest.fn().mockReturnValue({
      select: jest.fn().mockReturnValue({
        limit: jest.fn().mockResolvedValue({ data: [], error: null })
      })
    })
  }
}))

describe('Datenbank Client', () => {
  it('sollte ohne Fehler importieren', async () => {
    const db = await import('../../lib/db')
    expect(db.supabase).toBeDefined()
  })

  it('initDatabase sollte eine Funktion sein', async () => {
    const { initDatabase } = await import('../../lib/db')
    expect(typeof initDatabase).toBe('function')
  })
})
